import { loadConfig, loadVault, persistVaultDelta } from "./persist.js";

type JsonValue = unknown;

export function registerHooks(pi: ExtensionAPI, redactor: RedactorService): void {
  const statusText = () => (redactor.isEnabled() ? "PII: On" : "PII: Off");
  const restore = (text: string) => redactor.restore(text);
  const vaultHasEntries = () => redactor.getVault().size > 0;

  /** Redacts one string and counts redactions, for use as a deep-walker callback. */
  const counter = () => {
    const state = { count: 0 };
    const fn = async (text: string): Promise<string> => {
      const result = await redactor.redact(text);
      state.count += result.count;
      return result.text;
    };
    return { state, fn };
  };

  const compactionActive = () => redactor.isEnabled() && redactor.getConfig().maskContextMessages;

  /** Resolves the model and auth used to summarize, or notifies and returns null. */
  const resolveModelAuth = async (ctx: ExtensionContext, what: string) => {
    const model = ctx?.model;
    if (!model) {
      ctx?.ui?.notify?.(`PII redaction: no model available for ${what}; cancelled to avoid leaking plaintext`, "error");
      return null;
    }
    const auth = await ctx.modelRegistry.getApiKeyAndHeaders(model);
    if (!auth.ok) {
      ctx?.ui?.notify?.(`PII redaction: ${what} auth failed (${auth.error}); cancelled to avoid leaking plaintext`, "error");
      return null;
    }
    // Provider headers may carry null (= "remove header"); the summarizers only accept strings.
    const headers: Record<string, string> = {};
    for (const [k, v] of Object.entries(auth.headers ?? {})) {
      if (typeof v === "string") headers[k] = v;
    }
    return { model, apiKey: auth.apiKey, headers };
  };

  // Restore the vault and settings from the session, and update the footer status
  pi.on("session_start", async (_event, ctx) => {
    const entries = ctx?.sessionManager?.getEntries?.() ?? [];
    if (ctx?.sessionManager) {
      loadVault(entries, redactor);
      loadConfig(entries, redactor);
    }
    ctx?.ui?.setStatus?.("pii-redact", statusText());
  });

  // Intercept user prompts before expansion or dispatch
  pi.on("input", async (event, ctx) => {
    if (!redactor.isEnabled() || !redactor.getConfig().maskUserInputs) {
      return undefined;
    }

    if (!event || typeof event.text !== "string") {
      return undefined;
    }

    const result = await redactor.redact(event.text);
    persistVaultDelta(pi, redactor);
    if (result.hasRedactions) {
      if (redactor.getConfig().notifyOnRedact) {
        ctx?.ui?.notify?.(`Redacted ${result.count} sensitive item(s) from input`, "info");
      }
      return { action: "transform", text: result.text };
    }
    return undefined;
  });

  // Restore tokens in tool arguments so tools operate on real values (works even while redaction is off)
  pi.on("tool_call", async (event) => {
    if (!event?.input || typeof event.input !== "object" || !vaultHasEntries()) {
      return undefined;
    }
    restoreStringsInPlace(event.input, restore);
    return undefined;
  });

  // Restore assistant replies to plaintext at rest (thinking blocks stay byte-identical)
  pi.on("message_end", async (event) => {
    if (!event?.message || (event.message as any).role !== "assistant" || !vaultHasEntries()) {
      return undefined;
    }
    const restored = await restoreAssistantMessage(event.message, restore);
    return restored !== event.message ? { message: restored } : undefined;
  });

  // Intercept tool results (e.g. read_file, bash output) before storing in session & sending to model
  pi.on("tool_result", async (event, ctx) => {
    if (!redactor.isEnabled() || !redactor.getConfig().maskToolResults) {
      return undefined;
    }

    if (!event || !Array.isArray(event.content)) {
      return undefined;
    }

    const { state, fn } = counter();
    const content = await mapContent(event.content, fn);
    const hasStructured = event.structuredContent !== undefined;
    const structuredContent = hasStructured ? await mapStringsDeep(event.structuredContent as JsonValue, fn) : undefined;
    persistVaultDelta(pi, redactor);

    if (content !== event.content || structuredContent !== event.structuredContent) {
      if (redactor.getConfig().notifyOnRedact) {
        const toolLabel = event?.toolName ? `${event.toolName} output` : "tool output";
        ctx?.ui?.notify?.(`Redacted ${state.count} item(s) from ${toolLabel}`, "info");
      }
      return (hasStructured ? { content, structuredContent } : { content }) as ToolResultEventResult;
    }

    return undefined;
  });

  // Intercept messages in context before LLM requests (all roles; inputs are never mutated)
  pi.on("context", async (event) => {
    if (!redactor.isEnabled() || !redactor.getConfig().maskContextMessages) {
      return undefined;
    }

    if (!event || !Array.isArray(event.messages)) {
      return undefined;
    }

    const { fn } = counter();
    const { messages, changed } = await mapMessages(event.messages, fn);
    persistVaultDelta(pi, redactor);
    return changed ? { messages } : undefined;
  });

  // Compaction calls the model directly, bypassing `context`: take it over with redacted input
  pi.on("session_before_compact", async (event, ctx) => {
    if (!compactionActive()) return undefined;

    try {
      const auth = await resolveModelAuth(ctx, "compaction");
      if (!auth) return { cancel: true };

      const { fn } = counter();
      const prep = event.preparation;
      const preparation = {
        ...prep,
        messagesToSummarize: (await mapMessages(prep.messagesToSummarize ?? [], fn)).messages,
        turnPrefixMessages: (await mapMessages(prep.turnPrefixMessages ?? [], fn)).messages,
        previousSummary: prep.previousSummary ? await fn(prep.previousSummary) : prep.previousSummary,
      };
      const instructions = event.customInstructions ? await fn(event.customInstructions) : undefined;

      const result = await compact(preparation, auth.model, auth.apiKey, auth.headers, instructions, event.signal);
      return { compaction: { ...result, summary: restore(result.summary) } };
    } catch (error) {
      if (!event.signal?.aborted) {
        const message = error instanceof Error ? error.message : String(error);
        ctx?.ui?.notify?.(`PII redaction: compaction failed (${message}); cancelled to avoid leaking plaintext`, "error");
      }
      return { cancel: true };
    } finally {
      persistVaultDelta(pi, redactor);
    }
  });

  // Branch summaries also call the model directly
  pi.on("session_before_tree", async (event, ctx) => {
    if (!compactionActive() || !event?.preparation?.userWantsSummary) return undefined;

    try {
      const auth = await resolveModelAuth(ctx, "branch summary");
      if (!auth) return { cancel: true };

      const { fn } = counter();
      const prep = event.preparation;
      const entries: any[] = [];
      for (const entry of prep.entriesToSummarize ?? []) {
        entries.push(await mapSessionEntry(entry, fn));
      }
      const instructions = prep.customInstructions ? await fn(prep.customInstructions) : undefined;

      const result = await generateBranchSummary(entries, {
        model: auth.model,
        apiKey: auth.apiKey,
        headers: auth.headers,
        signal: event.signal,
        customInstructions: instructions,
        replaceInstructions: prep.replaceInstructions,
      });
      if (result.aborted) return { cancel: true };
      if (result.error || !result.summary) {
        throw new Error(result.error ?? "empty summary");
      }
      return {
        summary: {
          summary: restore(result.summary),
          details: { readFiles: result.readFiles ?? [], modifiedFiles: result.modifiedFiles ?? [] },
          usage: result.usage,
        },
      };
    } catch (error) {
      if (!event.signal?.aborted) {
        const message = error instanceof Error ? error.message : String(error);
        ctx?.ui?.notify?.(`PII redaction: branch summary failed (${message}); cancelled to avoid leaking plaintext`, "error");
      }
      return { cancel: true };
    } finally {
      persistVaultDelta(pi, redactor);
    }
  });

  pi.on("session_shutdown", async () => {
    redactor.dispose();
  });
}
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import type { RedactorService } from "../services/redactor.js";
import { PiiVault, type VaultPayload } from "../services/vault.js";

export const VAULT_ENTRY = "pii-vault";
export const CONFIG_ENTRY = "pii-config";

/** Persisted /pii settings. */
export interface PiiConfigEntry {
  enabled: boolean;
  /** Ids of rules that are disabled (snapshot of the full rule set). */
  disabledRules?: string[];
}

interface CustomEntryLike {
  type?: string;
  customType?: string;
  data?: unknown;
}

/** Appends newly minted vault entries to the session, if there are any. */
export function persistVaultDelta(pi: ExtensionAPI, redactor: RedactorService): void {
  const delta = redactor.getVault().takePendingDelta();
  if (delta) pi.appendEntry(VAULT_ENTRY, delta);
}

/** Appends the current /pii settings to the session. */
export function persistConfig(pi: ExtensionAPI, redactor: RedactorService): void {
  const data: PiiConfigEntry = {
    enabled: redactor.isEnabled(),
    disabledRules: redactor.getRules().filter((r) => !r.enabled).map((r) => r.id),
  };
  pi.appendEntry(CONFIG_ENTRY, data);
}

/** Rebuilds the vault from ALL pii-vault entries (every branch, so numbers are never reused). */
export function loadVault(entries: readonly CustomEntryLike[], redactor: RedactorService): void {
  const payloads = entries
    .filter((e) => e?.type === "custom" && e.customType === VAULT_ENTRY)
    .map((e) => e.data as VaultPayload);
  redactor.setVault(PiiVault.fromPayloads(payloads));
}

/** Applies the most recent pii-config entry, if any. */
export function loadConfig(entries: readonly CustomEntryLike[], redactor: RedactorService): void {
  const configs = entries.filter((e) => e?.type === "custom" && e.customType === CONFIG_ENTRY);
  const latest = configs[configs.length - 1]?.data as PiiConfigEntry | undefined;
  if (!latest || typeof latest.enabled !== "boolean") return;
  redactor.setEnabled(latest.enabled);
  if (Array.isArray(latest.disabledRules)) {
    const disabled = new Set(latest.disabledRules);
    for (const rule of redactor.getRules()) {
      redactor.toggleRule(rule.id, !disabled.has(rule.id));
    }
  }
}
import { randomInt } from "node:crypto";

/** A single persisted vault mapping. */
export interface VaultEntry {
  token: string;
  label: string;
  original: string;
}

/** JSON-serializable, versioned snapshot (or delta) of a vault, suitable for session persistence. */
export interface VaultPayload {
  v: 1;
  nonce: string;
  entries: VaultEntry[];
}

/** A located token inside a text. */
export interface TokenSpan {
  start: number;
  end: number;
  token: string;
}

const NONCE_ALPHABET = "REDACTED";
const NONCE_LENGTH = 4;
const STRICT_TOKEN_SHAPE = /^\[([A-Z][A-Z0-9_]*)_(\d+)#([a-z0-9]{4})\]$/;

function generateNonce(): string {
  let out = "";
  for (let i = 0; i < NONCE_LENGTH; i++) {
    out += NONCE_ALPHABET[randomInt(NONCE_ALPHABET.length)];
  }
  return out;
}

function normalizeLabel(label: string): string {
  const cleaned = label.toUpperCase().replace(/[^A-Z0-9_]/g, "_");
  return /^[A-Z]/.test(cleaned) ? cleaned : `X_${cleaned}`;
}

/**
 * Session-scoped two-way map between sensitive original values and stable tokens
 * of the form `[LABEL_N#nonce]`.
 *
 * - The same original always maps to the same token.
 * - Per-label counters only ever increase.
 * - The random nonce (created once per vault and persisted with it) makes tokens
 *   unforgeable by file contents: text that merely looks like `[EMAIL_1]` is never restored.
 */
export class PiiVault {
  private readonly nonce: string;
  private readonly byOriginal = new Map<string, VaultEntry>();
  private readonly byToken = REDACTED Map<string, VaultEntry>();
  private readonly byKey = new Map<string, VaultEntry>(); // "LABEL_N" -> entry
  private readonly counters = new Map<string, number>();
  private pending: VaultEntry[] = [];
  private readonly strictRegex: RegExp;
  private readonly tolerantRegex: RegExp;

  constructor(nonce?: string) {
    this.nonce = nonce && /^[a-z0-9]{4}$/.test(nonce) ? nonce : generateNonce();
    this.strictRegex = new RegExp(`\\[([A-Z][A-Z0-9_]*)_(\\d+)#${this.nonce}\\]`, "g");
    const label = "([A-Za-z][A-Za-z0-9_]*)_(\\d+)";
    this.tolerantRegex = new RegExp(
      `\\[\\s*${label}\\s*#\\s*${this.nonce}\\s*\\]|(?<![A-Za-z0-9_])${label}\\s*#\\s*${this.nonce}(?![A-Za-z0-9])`,
      "gi"
    );
  }

  /** Rebuilds a vault from persisted payloads: union of entries, first nonce wins, counters = max N per label. */
  public static fromPayloads(payloads: ReadonlyArray<VaultPayload | null | undefined>): PiiVault {
    const valid = payloads.filter(
      (p): p is VaultPayload =>
        !!p && typeof p === "object" && p.v === 1 && typeof p.nonce === "string" && Array.isArray(p.entries)
    );
    const firstNonce = valid.find((p) => /^[a-z0-9]{4}$/.test(p.nonce))?.nonce;
    const vault = new PiiVault(firstNonce);
    for (const payload of valid) {
      for (const e of payload.entries) {
        if (!e || typeof e.token !== "string" || typeof e.label !== "string" || typeof e.original !== "string") {
          continue;
        }
        const m = STRICT_TOKEN_SHAPE.exec(e.token);
        if (!m || m[3] !== vault.nonce) continue; // foreign nonce: could never be restored by this vault
        vault.insert({ token: e.token, label: m[1], original: e.original }, parseInt(m[2], 10));
      }
    }
    vault.pending = [];
    return vault;
  }

  private insert(entry: VaultEntry, n: number): boolean {
    if (this.byToken.has(entry.token) || this.byOriginal.has(entry.original)) return false;
    this.byOriginal.set(entry.original, entry);
    this.byToken.set(entry.token, entry);
    this.byKey.set(`${entry.label}_${n}`, entry);
    this.counters.set(entry.label, Math.max(this.counters.get(entry.label) ?? 0, n));
    this.pending.push(entry);
    return true;
  }

  /** Returns the existing token for `original`, or mints a new one under `label`. */
  public tokenFor(label: string, original: string): string {
    const existing = this.byOriginal.get(original);
    if (existing) return existing.token;
    const norm = normalizeLabel(label);
    const n = (this.counters.get(norm) ?? 0) + 1;
    const token = `[${norm}_${n}#${this.nonce}]`;
    this.insert({ token, label: norm, original }, n);
    return token;
  }

  /** Replaces this vault's tokens (tolerant matching) with their originals. Unknown tokens are left unchanged. */
  public restore(text: string): string {
    if (!text || typeof text !== "string") return text ?? "";
    if (this.byToken.size === 0) return text;
    return text.replace(this.tolerantRegex, (match, l1, n1, l2, n2) => {
      const label = String(l1 ?? l2).toUpperCase();
      const n = parseInt(String(n1 ?? n2), 10);
      const entry = this.byKey.get(`${label}_${n}`);
      return entry ? entry.original : match;
    });
  }

  /** True if `str` is exactly a canonical token of this vault. */
  public isKnownToken(str: string): boolean {
    return this.byToken.has(str);
  }

  /** Locates canonical tokens of this vault inside `text`. */
  public findTokens(text: string): TokenSpan[] {
    const spans: TokenSpan[] = [];
    if (!text || this.byToken.size === 0) return spans;
    this.strictRegex.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = this.strictRegex.exec(text)) !== null) {
      if (this.byToken.has(m[0])) {
        spans.push({ start: m.index, end: m.index + m[0].length, token: m[0] });
      }
    }
    return spans;
  }

  /** Known originals with their labels and tokens, longest first. */
  public knownOriginals(): VaultEntry[] {
    return Array.from(this.byOriginal.values()).sort((a, b) => b.original.length - a.original.length);
  }

  public get size(): number {
    return this.byToken.size;
  }

  /** Returns entries added since the previous call as a payload, or null if there are none. */
  public takePendingDelta(): VaultPayload | null {
    if (this.pending.length === 0) return null;
    const entries = this.pending;
    this.pending = [];
    return { v: 1, nonce: this.nonce, entries: entries.map((e) => ({ ...e })) };
  }

  /** Full JSON-serializable snapshot of the vault. */
  public toPayload(): VaultPayload {
    return {
      v: 1,
      nonce: this.nonce,
      entries: Array.from(this.byToken.values()).map((e) => ({ ...e })),
    };
  }
}
/**
 * Deep message walkers used by the hooks. All mapping helpers return the original
 * reference when nothing changed and never mutate their input.
 */

export type TextMapper = (text: string) => Promise<string>;

const MAX_DEPTH = 64;

/** Applies `fn` to every string value (not keys) nested in arrays/plain objects. Returns a copy only if changed. */
export async function mapStringsDeep<T>(value: T, fn: TextMapper, depth = 0): Promise<T> {
  if (typeof value === "string") {
    return (await fn(value)) as unknown as T;
  }
  if (depth > MAX_DEPTH || value === null || typeof value !== "object") {
    return value;
  }
  if (Array.isArray(value)) {
    let out: unknown[] | null = null;
    for (let i = 0; i < value.length; i++) {
      const next = await mapStringsDeep(value[i], fn, depth + 1);
      if (next !== value[i]) {
        out ??= value.slice();
        out[i] = next;
      }
    }
    return (out ?? value) as unknown as T;
  }
  const proto = Object.getPrototypeOf(value);
  if (proto !== Object.prototype && proto !== null) {
    return value;
  }
  let out: Record<string, unknown> | null = null;
  for (const key of Object.keys(value as Record<string, unknown>)) {
    const current = (value as Record<string, unknown>)[key];
    const next = await mapStringsDeep(current, fn, depth + 1);
    if (next !== current) {
      out ??= { ...(value as Record<string, unknown>) };
      out[key] = next;
    }
  }
  return (out ?? value) as T;
}

/** Restores every string nested in `value` in place, keeping the existing objects. Returns true if anything changed. */
export function restoreStringsInPlace(
  value: unknown,
  restore: (text: string) => string,
  depth = 0,
  seen: WeakSet<object> = new WeakSet()
): boolean {
  if (depth > MAX_DEPTH || value === null || typeof value !== "object") return false;
  if (seen.has(value)) return false;
  seen.add(value);
  let changed = false;
  const container = value as Record<string, unknown>;
  for (const key of Object.keys(container)) {
    const current = container[key];
    if (typeof current === "string") {
      const next = restore(current);
      if (next !== current) {
        container[key] = next;
        changed = true;
      }
    } else if (restoreStringsInPlace(current, restore, depth + 1, seen)) {
      changed = true;
    }
  }
  return changed;
}

/** Maps string content or the text blocks of a block array. Other blocks (images, ...) are untouched. */
export async function mapContent(content: unknown, fn: TextMapper): Promise<unknown> {
  if (typeof content === "string") return fn(content);
  if (!Array.isArray(content)) return content;
  let out: unknown[] | null = null;
  for (let i = 0; i < content.length; i++) {
    const block = content[i] as any;
    if (block && typeof block === "object" && block.type === "text" && typeof block.text === "string") {
      const text = await fn(block.text);
      if (text !== block.text) {
        out ??= content.slice();
        out[i] = { ...block, text };
      }
    }
  }
  return out ?? content;
}

/** Maps assistant content: text blocks and toolCall arguments. Thinking (and every other block) is never touched. */
export async function mapAssistantContent(content: unknown, fn: TextMapper): Promise<unknown> {
  if (typeof content === "string") return fn(content);
  if (!Array.isArray(content)) return content;
  let out: unknown[] | null = null;
  for (let i = 0; i < content.length; i++) {
    const block = content[i] as any;
    if (!block || typeof block !== "object") continue;
    let next = block;
    if (block.type === "text" && typeof block.text === "string") {
      const text = await fn(block.text);
      if (text !== block.text) next = { ...block, text };
    } else if (block.type === "toolCall" && block.arguments && typeof block.arguments === "object") {
      const args = await mapStringsDeep(block.arguments, fn);
      if (args !== block.arguments) next = { ...block, arguments: args };
    }
    if (next !== block) {
      out ??= content.slice();
      out[i] = next;
    }
  }
  return out ?? content;
}

async function withField<T extends Record<string, any>>(
  msg: T,
  field: string,
  mapper: (v: unknown) => Promise<unknown>,
  extra?: T
): Promise<T> {
  const base = extra ?? msg;
  const next = await mapper(base[field]);
  return next === base[field] ? base : ({ ...base, [field]: next } as T);
}

/**
 * Maps all model-visible text of an AgentMessage. Returns the same reference when unchanged,
 * otherwise a copy. The input is never mutated.
 */
export async function mapMessage<T>(message: T, fn: TextMapper): Promise<T> {
  const msg = message as any;
  if (!msg || typeof msg !== "object") return message;

  switch (msg.role) {
    case "assistant":
      return withField(msg, "content", (c) => mapAssistantContent(c, fn));
    case "bashExecution": {
      if (msg.excludeFromContext) return message;
      let out = msg;
      if (typeof out.output === "string") out = await withField(msg, "output", (v) => mapStringsDeep(v, fn), out);
      if (typeof out.command === "string") out = await withField(msg, "command", (v) => mapStringsDeep(v, fn), out);

